import { useState, useEffect } from "react";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { useForm } from "react-hook-form";
import SocialMediaIcons from "../components/SocialMediaIcons";
import LockInput from "../components/ui/lock-input";
import MorphingButton from "../components/ui/morphing-button";

const CONTACT_SENT_KEY = "hreem-contact-form-sent";
const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const Contact = ({ isDarkMode }) => {
  const reduceMotion = useReducedMotion();
  const [sent, setSent] = useState(false);
  const [error, setError] = useState(null);
  // Brief "Failed" flash on the button; the error text below stays until the next try.
  const [failedFlash, setFailedFlash] = useState(false);

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors, isSubmitting },
  } = useForm({ mode: "onTouched" });

  useEffect(() => {
    try {
      if (sessionStorage.getItem(CONTACT_SENT_KEY)) setSent(true);
    } catch {
      /* private mode / storage blocked */
    }
  }, []);

  const onSubmit = async (data) => {
    setError(null);
    try {
      const body = new FormData();
      Object.entries(data).forEach(([key, value]) => body.append(key, value));
      body.append("_captcha", "false");

      const res = await fetch("https://formsubmit.co/ajax/hreempandya@gmail.com", {
        method: "POST",
        body,
        headers: { Accept: "application/json" },
      });
      if (!res.ok) throw new Error("Request failed");

      reset();
      setSent(true);
      try {
        sessionStorage.setItem(CONTACT_SENT_KEY, String(Date.now()));
      } catch {
        /* ignore */
      }
    } catch {
      setError("Something went wrong. Please try again or email directly.");
      setFailedFlash(true);
    }
  };

  useEffect(() => {
    if (!failedFlash) return undefined;
    const t = setTimeout(() => setFailedFlash(false), 2500);
    return () => clearTimeout(t);
  }, [failedFlash]);

  const buttonStatus = sent ? "success" : isSubmitting ? "loading" : failedFlash ? "error" : "idle";

  const fieldError = (name, id) => (
    <AnimatePresence initial={false}>
      {errors[name] && (
        <motion.p
          id={id}
          role="alert"
          initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -4, height: 0 }}
          animate={reduceMotion ? { opacity: 1 } : { opacity: 1, y: 0, height: "auto" }}
          exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -4, height: 0 }}
          transition={{ duration: 0.18 }}
          className={`mt-1.5 text-xs ${isDarkMode ? "text-red-400" : "text-red-500"}`}
        >
          {errors[name].message}
        </motion.p>
      )}
    </AnimatePresence>
  );

  return (
    <section
      id="contact"
      className={`pt-8 md:pt-12 pb-8 md:pb-14 transition-colors duration-300 relative overflow-hidden`}
    >
      {isDarkMode && (
        <div className="absolute inset-0 pointer-events-none overflow-hidden">
          <div className="absolute -top-32 -right-32 w-[500px] h-[500px] rounded-full bg-amber-500/[0.04] blur-[120px]" />
        </div>
      )}

      <div className="relative z-10 max-w-2xl mx-auto px-4 md:px-6">
        {/* Minimal: one-line caption, then a compact horizontal form */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.5 }}
        >
          <h2
            className={`mb-5 font-playfair text-lg md:text-xl font-bold ${
              isDarkMode ? "text-white" : "text-[var(--lm-text-primary)]"
            }`}
          >
            Drop me a message
          </h2>

          <form
            action="https://formsubmit.co/hreempandya@gmail.com"
            method="POST"
            className="space-y-4"
            onSubmit={handleSubmit(onSubmit)}
            noValidate
          >
            <input type="hidden" name="_captcha" value="false" />

            {/* Name + email side by side */}
            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 sm:gap-5">
              <div>
                <LockInput
                  isDarkMode={isDarkMode}
                  hasError={!!errors.name}
                  type="text"
                  placeholder="Your name"
                  aria-invalid={!!errors.name}
                  aria-describedby={errors.name ? "name-error" : undefined}
                  disabled={sent}
                  {...register("name", { required: "Please enter your name." })}
                />
                {fieldError("name", "name-error")}
              </div>

              <div>
                <LockInput
                  isDarkMode={isDarkMode}
                  hasError={!!errors.email}
                  type="email"
                  placeholder="Email"
                  aria-invalid={!!errors.email}
                  aria-describedby={errors.email ? "email-error" : undefined}
                  disabled={sent}
                  {...register("email", {
                    required: "Please enter your email.",
                    pattern: { value: EMAIL_PATTERN, message: "Enter a valid email address." },
                  })}
                />
                {fieldError("email", "email-error")}
              </div>
            </div>

            <div>
              <LockInput
                as="textarea"
                isDarkMode={isDarkMode}
                hasError={!!errors.message}
                className="min-h-[96px] resize-none"
                placeholder="Your message"
                rows={3}
                aria-invalid={!!errors.message}
                aria-describedby={errors.message ? "message-error" : undefined}
                disabled={sent}
                {...register("message", {
                  required: "Please enter a message.",
                  minLength: { value: 10, message: "A little more detail, please (10+ characters)." },
                })}
              />
              {fieldError("message", "message-error")}
            </div>

            <div className="flex flex-col sm:flex-row items-start sm:items-center gap-4 pt-1">
              <MorphingButton
                type="submit"
                status={buttonStatus}
                disabled={sent}
                isDarkMode={isDarkMode}
                idleText="Send message"
                loadingText="Sending..."
                successText="Message sent, thanks!"
                errorText="Not sent"
              />

              {error && (
                <span className={`text-sm ${isDarkMode ? "text-red-400" : "text-red-600"}`} role="alert">
                  {error}
                </span>
              )}
            </div>
          </form>
        </motion.div>

        {/* Email + social — inline, no boxes */}
        <motion.div
          className="mt-6 pt-5 border-t flex flex-col sm:flex-row items-start sm:items-center justify-between gap-6 md:mt-8 md:pt-6"
          style={{
            borderColor: isDarkMode ? "rgba(255,255,255,0.06)" : "var(--lm-border)",
          }}
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
          transition={{ delay: 0.2 }}
        >
          <a
            href="mailto:hreempandya@gmail.com"
            className={`font-medium text-sm hover:opacity-80 transition-opacity ${
              isDarkMode ? "text-amber-400" : "text-[var(--lm-accent)]"
            }`}
          >
            hreempandya@gmail.com
          </a>
          <div className="-my-6 md:-my-4">
              <SocialMediaIcons isDarkMode={isDarkMode} forceWhite={isDarkMode} />
            </div>
        </motion.div>
      </div>
    </section>
  );
};

export default Contact;
